list_products.code:
final response =
    await client.products.listProducts(queryParams: {'limit': 20});
final result = response.map as Map;
for (final product in result['products'] as List) {
  print('${(product as Map)['id']} ${product['name']} ${product['sku']}');
}
final pagination = result['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

